305	    /**
306	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
307	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
308	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
309	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
310	     * string is what gets stored and returned.
311	     *
312	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
313	     *
314	     * @param telephone the raw telephone value supplied by the client
315	     * @return the normalized E.164 telephone number
316	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
317	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
318	     *                                 digits after the {@code '+'})
319	     */
320	    private static String normalizeTelephone(String telephone) {
321	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
322	        String digits;
323	        if (cleaned.startsWith("+")) {
324	            digits = cleaned.substring(1);
325	        } else {
326	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
327	            digits = "61" + national;
328	        }
329	        if (!digits.matches("[0-9]{8,15}")) {
330	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
331	                "telephone could not be normalized to a valid E.164 number");
332	        }
333	        return "+" + digits;
334	    }
