337	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
338	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
339	     *
340	     * @param telephone the stored telephone value, possibly {@code null}
341	     * @return the E.164 form, or the raw value when it cannot be normalized
342	     */
343	    private static String toComparableTelephone(String telephone) {
344	        try {
345	            return normalizeTelephone(telephone);
346	        } catch (ResponseStatusException ex) {
347	            return telephone;
348	        }
349	    }
