417	    /**
418	     * Determines whether the given normalized E.164 telephone is already used by any owner other
419	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
420	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
421	     * inputs representing the same number are treated as duplicates.
422	     *
423	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
424	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
425	     * @return {@code true} if another owner already uses the telephone
426	     */
427	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
428	        for (Owner existing : this.clinicService.findAllOwners()) {
429	            if (excludeId != null && excludeId.equals(existing.getId())) {
430	                continue;
431	            }
432	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
433	                return true;
434	            }
435	        }
436	        return false;
437	    }
